      (rf'^周末的时候，(.+?)喜欢去({places})(.+?)。$', lambda m:f'Cuối tuần, {repl_words(m.group(1))} thích đi {repl_words(m.group(2))} để {repl_words(m.group(3))}.'),
      (r'^(.+?)觉得(.+?)很重要。$', lambda m:f'{repl_words(m.group(1))} cho rằng {repl_words(m.group(2))} rất quan trọng.'),
      (rf'^经过讨论，(.+?)决定在({places})(.+?)。$', lambda m:f'Sau khi thảo luận, {repl_words(m.group(1))} quyết định {repl_words(m.group(3))} ở {repl_words(m.group(2))}.'),
      (r'^为了准备明天的工作，(.+?)今晚还要(.+?)。$', lambda m:f'Để chuẩn bị cho công việc ngày mai, tối nay {repl_words(m.group(1))} còn phải {repl_words(m.group(2))}.'),
      (r'^最近(.+?)常常需要(.+?)。$', lambda m:f'Gần đây {repl_words(m.group(1))} thường xuyên cần {repl_words(m.group(2))}.'),
      (rf'^如果计划没有变化，(.+?)下午会在({places})(.+?)。$', lambda m:f'Nếu kế hoạch không thay đổi, buổi chiều {repl_words(m.group(1))} sẽ {repl_words(m.group(3))} ở {repl_words(m.group(2))}.'),
      (rf'^(.+?)已经把(.+?)带到({places})了。$', lambda m:f'{repl_words(m.group(1))} đã mang {repl_words(m.group(2))} đến {repl_words(m.group(3))}.'),
      (r'^(.+?)正在检查(.+?)，准备开始(.+?)。$', lambda m:f'{repl_words(m.group(1))} đang kiểm tra {repl_words(m.group(2))}, chuẩn bị bắt đầu {repl_words(m.group(3))}.'),
      (rf'^会议结束以后，(.+?)马上回到({places})继续(.+?)。$', lambda m:f'Sau khi cuộc họp kết thúc, {repl_words(m.group(1))} lập tức quay về {repl_words(m.group(2))} để tiếp tục {repl_words(m.group(3))}.'),
      (rf'^我听说(.+?)最近在({places})负责(.+?)。$', lambda m:f'Tôi nghe nói gần đây {repl_words(m.group(1))} phụ trách {repl_words(m.group(3))} ở {repl_words(m.group(2))}.'),
